import React, { useState, useEffect } from 'react'; // 1. Importa useEffect
import { AuthProvider, useAuth } from './AuthContext'; // Asegura la ruta correcta
// ... tus otros imports ...

// 2. CREAMOS UN COMPONENTE INTERNO QUE CONTENGA LA LÓGICA DE NAVEGACIÓN
// Esto es necesario porque necesitamos usar useAuth(), y useAuth solo funciona
// DENTRO de AuthProvider.
const AppContent = () => {
    const { user, isAuthenticated } = useAuth();
    const [currentPage, setCurrentPage] = useState('home');

    // HOOK DE BURBUJAS (Tu hook original)
    useBubbles && useBubbles('.container'); 

    // 3. EFECTO MÁGICO: REDIRECCIÓN AUTOMÁTICA AL RECARGAR
    useEffect(() => {
        if (isAuthenticated && user) {
            // Si existe usuario guardado y estamos en home o login, lo mandamos a su pagina
            if (currentPage === 'home' || currentPage === 'login') {
                if (user.role === 'cliente') setCurrentPage('servicios');
                else if (user.role === 'trabajador') setCurrentPage('tareas'); // si existe
                // etc...
            }
        }
    }, [isAuthenticated, user]); // Se ejecuta cuando cambia el estado de autenticación

    // Funciones de navegación
    const goToHome = () => setCurrentPage('home');
    const goToLogin = () => setCurrentPage('login');
    const goToServicios = () => setCurrentPage('servicios');

    // Función que se ejecuta tras login exitoso
    const handleLoginSuccess = (role) => {
        if (role === 'cliente') goToServicios();
        else goToHome();
    };

    // Renderizado condicional
    switch (currentPage) {
        case 'login':
            return <LoginPage onBackToHome={goToHome} onLoginSuccess={handleLoginSuccess} />;
        case 'servicios':
            return <ServiciosClientePage onBackToHome={goToHome} />;
        case 'home':
        default:
            // TU HOME ORIGINAL
            return (
                // ... tu JSX del home ...
                // Asegúrate de pasar onLoginClick={goToLogin} a tu Header
                 <>
                    <div className="background-image-container"></div>
                    <div className="container">
                        <Header onLoginClick={goToLogin} />
                        <MainContent onServiciosClick={goToServicios} />
                        <div className="foam-effect"></div>
                        <Footer />
                    </div>
                </>
            );
    }
};

// 4. COMPONENTE PRINCIPAL
const App = () => {
    return (
        <AuthProvider>
            <AppContent />
        </AuthProvider>
    );
};

export default App;
